pub const V_NOT_RUN: u8 = 4;

#[allow(non_upper_case_globals)]
pub const tri_lab_receipt__V_RED: u8 = 5;

pub const V_UNREAD: u8 = 6;

pub const V_VACUOUS: u8 = 1;

pub const V_VERIFIED: u8 = 0;

pub fn line_end(text: &'static str, at: usize) -> usize {
    let mut k: usize = at;
    while ((k < text.len()) && (text.as_bytes()[(k) as usize] != 10)) {
        k = (k + 1);
    }
    return k;
}

pub fn listed(v: u8, pattern_given: bool) -> bool {
    if pattern_given {
        return true;
    }
    return ((v == tri_lab_receipt__V_RED) || (v == V_UNREAD));
}

pub fn tri_lab_receipt__name(v: u8) -> &'static str {
    if (v == V_VERIFIED) {
        return "verified";
    }
    if (v == V_VACUOUS) {
        return "vacuous";
    }
    if (v == tri_lab_receipt__V_BEHIND) {
        return "behind";
    }
    if (v == tri_lab_receipt__V_BLOCKED) {
        return "blocked";
    }
    if (v == V_NOT_RUN) {
        return "not-run";
    }
    if (v == tri_lab_receipt__V_RED) {
        return "RED";
    }
    return "UNREAD";
}

pub fn span_is(text: &'static str, from: usize, to: usize, lit: &'static str) -> bool {
    if ((to < from) || ((to - from) != lit.len())) {
        return false;
    }
    let mut k: usize = 0;
    while (k < lit.len()) {
        if (text.as_bytes()[((from + k)) as usize] != lit.as_bytes()[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub const UNKNOWN: &'static str = "?";

pub fn branch_from(w: &'static str, at: usize) -> usize {
    let stop: usize = record_end(w, at);
    let mut k: usize = at;
    while (k < stop) {
        if starts(w, k, "branch refs/heads/") {
            return (k + 18);
        }
        k = (line_end(w, k) + 1);
    }
    return w.len();
}

pub fn branch_to(w: &'static str, at: usize) -> usize {
    let b: usize = branch_from(w, at);
    if (b >= w.len()) {
        return w.len();
    }
    return line_end(w, b);
}

pub fn digits(text: &'static str, from: usize, to: usize) -> u64 {
    if ((to <= from) || ((to - from) > 18)) {
        return 0;
    }
    let mut n: u64 = 0;
    let mut i: usize = from;
    while (i < to) {
        if ((text.as_bytes()[(i) as usize] < 48) || (text.as_bytes()[(i) as usize] > 57)) {
            return 0;
        }
        n = ((n * 10) + ((text.as_bytes()[(i) as usize] as u64) - 48));
        i = (i + 1);
    }
    return n;
}

pub fn merged(m: &'static str, w: &'static str, at: usize) -> bool {
    let b: usize = branch_from(w, at);
    let be: usize = branch_to(w, at);
    if (b >= w.len()) {
        return false;
    }
    let mut k: usize = 0;
    while ((((k + 15) + (be - b)) + 1) <= m.len()) {
        if (span_is(m, k, (k + 15), "\"headRefName\":\"") && (m.as_bytes()[(((k + 15) + (be - b))) as usize] == 34)) {
            let mut same: bool = true;
            let mut i: usize = 0;
            while (i < (be - b)) {
                if (m.as_bytes()[(((k + 15) + i)) as usize] != w.as_bytes()[((b + i)) as usize]) {
                    same = false;
                }
                i = (i + 1);
            }
            if same {
                return true;
            }
        }
        k = (k + 1);
    }
    return false;
}

pub fn record_end(w: &'static str, at: usize) -> usize {
    let mut k: usize = at;
    while (k < w.len()) {
        let end: usize = line_end(w, k);
        if (end == k) {
            return k;
        }
        k = (end + 1);
    }
    return w.len();
}

pub fn starts(w: &'static str, at: usize, lit: &'static str) -> bool {
    if ((at + lit.len()) > w.len()) {
        return false;
    }
    return span_is(w, at, (at + lit.len()), lit);
}

pub const MAX_DIGITS: usize = 18;

pub const NO_EXIT: u64 = 256;

pub const RULES: u8 = 13;

pub const STEPS: u8 = 19;

pub fn body_from(ev: &'static str, k: u8, n: u64) -> usize {
    let s: usize = section(ev, k, n);
    if (s >= ev.len()) {
        return ev.len();
    }
    return header_end(ev, s);
}

pub fn body_to(ev: &'static str, k: u8, n: u64) -> usize {
    let s: usize = section(ev, k, n);
    if (s >= ev.len()) {
        return ev.len();
    }
    return (header_end(ev, s) + (field(ev, s, 3) as usize));
}

pub fn digits_end(text: &'static str, at: usize, to: usize) -> usize {
    let mut k: usize = at;
    while (((k < to) && (text.as_bytes()[(k) as usize] >= 48)) && (text.as_bytes()[(k) as usize] <= 57)) {
        k = (k + 1);
    }
    return k;
}

pub fn entries(c: &'static str) -> u64 {
    let mut n: u64 = 0;
    while (entry_at(c, n) < c.len()) {
        n = (n + 1);
    }
    return n;
}

pub fn entry_at(c: &'static str, n: u64) -> usize {
    let mut at: usize = 0;
    let mut seen: u64 = 0;
    while (at < c.len()) {
        let end: usize = line_end(c, at);
        if (end > at) {
            if (seen == n) {
                return at;
            }
            seen = (seen + 1);
        }
        at = (end + 1);
    }
    return c.len();
}

pub fn exit_of(ev: &'static str, k: u8, n: u64) -> u64 {
    let s: usize = section(ev, k, n);
    if (s >= ev.len()) {
        return NO_EXIT;
    }
    return field(ev, s, 2);
}

pub fn field(ev: &'static str, at: usize, f: u64) -> u64 {
    let mut k: usize = (at + 13);
    let mut i: u64 = 0;
    while (i < f) {
        k = (digits_end(ev, k, ev.len()) + 1);
        i = (i + 1);
    }
    return digits(ev, k, digits_end(ev, k, ev.len()));
}

pub fn find_in(text: &'static str, from: usize, to: usize, lit: &'static str) -> usize {
    let mut k: usize = from;
    while ((k + lit.len()) <= to) {
        if span_is(text, k, (k + lit.len()), lit) {
            return k;
        }
        k = (k + 1);
    }
    return (text.len() + 1);
}

pub fn has_line(text: &'static str, from: usize, to: usize, lit: &'static str) -> bool {
    return (line_after(text, from, to, lit) <= text.len());
}

pub fn header_end(ev: &'static str, at: usize) -> usize {
    if (at >= ev.len()) {
        return (ev.len() + 1);
    }
    let end: usize = line_end(ev, at);
    if ((end >= ev.len()) || (opens_with(ev, at, end, "@@ preflight ") == false)) {
        return (ev.len() + 1);
    }
    let mut k: usize = (at + 13);
    let mut f: u64 = 0;
    while (f < 4) {
        let e: usize = digits_end(ev, k, end);
        if ((e == k) || ((e - k) > MAX_DIGITS)) {
            return (ev.len() + 1);
        }
        k = e;
        if (f < 3) {
            if ((k >= end) || (ev.as_bytes()[(k) as usize] != 32)) {
                return (ev.len() + 1);
            }
            k = (k + 1);
        }
        f = (f + 1);
    }
    if (k != end) {
        return (ev.len() + 1);
    }
    return (end + 1);
}

pub fn is_spec(c: &'static str, n: u64) -> bool {
    let s: u8 = status(c, n);
    if ((s != 65) && (s != 77)) {
        return false;
    }
    return (path_is(c, n, "specs/", ".t27") && (path_is(c, n, "specs/scratch/", "") == false));
}

pub fn is_target(c: &'static str, n: u64) -> bool {
    return (is_spec(c, n) && path_safe(c, n));
}

pub fn line_after(text: &'static str, from: usize, to: usize, lit: &'static str) -> usize {
    let mut at: usize = from;
    while (at < to) {
        let mut end: usize = line_end(text, at);
        if (end > to) {
            end = to;
        }
        let mut k: usize = at;
        while ((k < end) && ((text.as_bytes()[(k) as usize] == 32) || (text.as_bytes()[(k) as usize] == 9))) {
            k = (k + 1);
        }
        if opens_with(text, k, end, lit) {
            return (k + lit.len());
        }
        at = (end + 1);
    }
    return (text.len() + 1);
}

pub fn next_section(ev: &'static str, at: usize) -> usize {
    let he: usize = header_end(ev, at);
    if (he > ev.len()) {
        return (ev.len() + 1);
    }
    let len: u64 = field(ev, at, 3);
    if (len >= ((ev.len() - he) as u64)) {
        return (ev.len() + 1);
    }
    let to: usize = (he + (len as usize));
    if (ev.as_bytes()[(to) as usize] != 10) {
        return (ev.len() + 1);
    }
    return (to + 1);
}

pub fn opens_with(text: &'static str, at: usize, end: usize, lit: &'static str) -> bool {
    if (at > end) {
        return false;
    }
    if (lit.len() > (end - at)) {
        return false;
    }
    return span_is(text, at, (at + lit.len()), lit);
}

pub fn path_end(c: &'static str, n: u64) -> usize {
    if (well_formed(c, n) == false) {
        return c.len();
    }
    return line_end(c, entry_at(c, n));
}

pub fn path_is(c: &'static str, n: u64, lit: &'static str, tail: &'static str) -> bool {
    let from: usize = path_start(c, n);
    let to: usize = path_end(c, n);
    if ((from >= to) || ((to - from) < (lit.len() + tail.len()))) {
        return false;
    }
    return (span_is(c, from, (from + lit.len()), lit) && span_is(c, (to - tail.len()), to, tail));
}

pub fn path_safe(c: &'static str, n: u64) -> bool {
    let from: usize = path_start(c, n);
    let to: usize = path_end(c, n);
    if (from >= to) {
        return false;
    }
    let mut k: usize = from;
    while (k < to) {
        let b: u8 = c.as_bytes()[(k) as usize];
        let ok: bool = (((((((((b >= 97) && (b <= 122)) || ((b >= 65) && (b <= 90))) || ((b >= 48) && (b <= 57))) || (b == 46)) || (b == 95)) || (b == 47)) || (b == 43)) || (b == 45));
        if (ok == false) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn path_start(c: &'static str, n: u64) -> usize {
    if (well_formed(c, n) == false) {
        return c.len();
    }
    return (entry_at(c, n) + 2);
}

pub fn same(a: &'static str, af: usize, b: &'static str, bf: usize, bt: usize) -> bool {
    if ((bt < bf) || ((af + (bt - bf)) > a.len())) {
        return false;
    }
    let mut i: usize = 0;
    while (i < (bt - bf)) {
        if (a.as_bytes()[((af + i)) as usize] != b.as_bytes()[((bf + i)) as usize]) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

pub fn section(ev: &'static str, k: u8, n: u64) -> usize {
    let mut at: usize = 0;
    while (at < ev.len()) {
        let nx: usize = next_section(ev, at);
        if (nx > ev.len()) {
            return (ev.len() + 1);
        }
        if ((field(ev, at, 0) == (k as u64)) && (field(ev, at, 1) == n)) {
            return at;
        }
        at = nx;
    }
    return (ev.len() + 1);
}

pub fn status(c: &'static str, n: u64) -> u8 {
    let at: usize = entry_at(c, n);
    if (at >= c.len()) {
        return 0;
    }
    return c.as_bytes()[(at) as usize];
}

pub fn well_formed(c: &'static str, n: u64) -> bool {
    let at: usize = entry_at(c, n);
    if (((at >= c.len()) || (line_end(c, at) < (at + 3))) || (c.as_bytes()[((at + 1)) as usize] != 9)) {
        return false;
    }
    let s: u8 = c.as_bytes()[(at) as usize];
    return ((((s == 65) || (s == 77)) || (s == 68)) || (s == 84));
}

