#[derive(Debug, Clone, Copy)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct TriRemoteReq {
    pub op: u8,
    pub host: &'static str,
    pub image: &'static str,
    pub name: &'static str,
    pub file: &'static str,
    pub dest: &'static str,
    pub url: &'static str,
    pub threads: u64,
    pub counter: u64,
    pub golden: bool,
}

pub const URL_MAX: usize = 200;

pub fn base_start(p: &'static str) -> usize {
    let mut b: usize = 0;
    let mut i: usize = 0;
    while (i < p.len()) {
        if (p.as_bytes()[(i) as usize] == 47) {
            b = (i + 1);
        }
        i = (i + 1);
    }
    return b;
}

pub fn buf_has(buf: &[u8], n: usize, want: &'static str) -> bool {
    if (((want.len() == 0) || (want.len() > n)) || (n > buf.len())) {
        return false;
    }
    let mut at: usize = 0;
    while ((at + want.len()) <= n) {
        let mut k: usize = 0;
        while ((k < want.len()) && (buf[((at + k)) as usize] == want.as_bytes()[(k) as usize])) {
            k = (k + 1);
        }
        if (k == want.len()) {
            return true;
        }
        at = (at + 1);
    }
    return false;
}

pub fn buf_is(buf: &[u8], n: usize, want: &'static str) -> bool {
    if ((n != want.len()) || (n > buf.len())) {
        return false;
    }
    let mut k: usize = 0;
    while (k < n) {
        if (buf[(k) as usize] != want.as_bytes()[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn command(r: TriRemoteReq, step: u8, out: &mut [u8]) -> usize {
    if (refusal(r) != R_OK) {
        return 0;
    }
    let mut w: usize = 0;
    if (r.op == OP_PING) {
        if (step != 0) {
            return 0;
        }
        w = emit_ssh(out, w, r.host);
        w = emit_str(out, w, "true\n");
        return fits(out, w);
    }
    if (r.op == OP_RUN) {
        let mut run_step: u8 = 2;
        if r.golden {
            run_step = 1;
        }
        if (step == 0) {
            w = emit_ssh(out, w, r.host);
            w = emit_str(out, w, "mkdir -p $HOME/t27-jobs/");
            w = emit_id(out, w, r);
            w = emit_byte(out, w, 10);
            return fits(out, w);
        }
        if ((step == 1) && (r.golden == false)) {
            w = emit_scp(out, w);
            w = emit_str(out, w, r.name);
            w = emit_byte(out, w, 10);
            w = emit_str(out, w, r.host);
            w = emit_str(out, w, ":t27-jobs/");
            w = emit_id(out, w, r);
            w = emit_str(out, w, "/deck.cir\n");
            return fits(out, w);
        }
        if (step == run_step) {
            w = emit_run_head(out, w, r);
            w = emit_script(out, w, r);
            w = emit_str(out, w, "\"\n");
            return fits(out, w);
        }
        return 0;
    }
    if (step != 0) {
        return 0;
    }
    if (r.op == OP_FETCH) {
        w = emit_scp(out, w);
        w = emit_str(out, w, r.host);
        w = emit_str(out, w, ":t27-jobs/");
        w = emit_str(out, w, r.name);
        w = emit_byte(out, w, 47);
        w = emit_str(out, w, r.file);
        w = emit_byte(out, w, 10);
        if (r.dest.len() == 0) {
            w = emit_byte(out, w, 46);
        } else {
            w = emit_str(out, w, r.dest);
        }
        w = emit_str(out, w, "/\n");
        return fits(out, w);
    }
    w = emit_ssh(out, w, r.host);
    if (r.op == OP_STATUS) {
        w = emit_str(out, w, "docker ps -a --filter \"name=^t27job-");
        w = emit_str(out, w, r.name);
        w = emit_str(out, w, "$\" --format \"{{.Names}} {{.Status}}\"\n");
        return fits(out, w);
    }
    if (r.op == OP_LOGS) {
        w = emit_str(out, w, "docker logs --tail 40 t27job-");
        w = emit_str(out, w, r.name);
        w = emit_str(out, w, "; tail -n 40 $HOME/t27-jobs/");
        w = emit_str(out, w, r.name);
        w = emit_str(out, w, "/ngspice.log\n");
        return fits(out, w);
    }
    w = emit_str(out, w, "docker rm -f t27job-");
    w = emit_str(out, w, r.name);
    w = emit_byte(out, w, 10);
    return fits(out, w);
}

pub fn emit_byte(out: &mut [u8], w: usize, c: u8) -> usize {
    if (w < out.len()) {
        out[(w) as usize] = c;
    }
    return (w + 1);
}

pub fn emit_dec(out: &mut [u8], w: usize, v: u64) -> usize {
    let mut div: u64 = 1;
    while ((v / div) >= 10) {
        div = (div * 10);
    }
    let mut p: usize = w;
    while (div > 0) {
        p = emit_byte(out, p, (48 + (((v / div) % 10) as u8)));
        div = (div / 10);
    }
    return p;
}

pub fn emit_id(out: &mut [u8], w: usize, r: TriRemoteReq) -> usize {
    if (r.op != OP_RUN) {
        return emit_str(out, w, r.name);
    }
    let mut p: usize = emit_stem(out, w, r.name);
    p = emit_byte(out, p, 45);
    return emit_dec(out, p, r.counter);
}

pub fn emit_run_head(out: &mut [u8], w: usize, r: TriRemoteReq) -> usize {
    let mut p: usize = emit_ssh(out, w, r.host);
    p = emit_str(out, p, "docker run -d --name t27job-");
    p = emit_id(out, p, r);
    p = emit_str(out, p, " -v $HOME/t27-jobs/");
    p = emit_id(out, p, r);
    p = emit_str(out, p, ":/work ");
    p = emit_str(out, p, r.image);
    return emit_str(out, p, " sh -c \"");
}

pub fn emit_scp(out: &mut [u8], w: usize) -> usize {
    return emit_str(out, w, "scp\n-o\nBatchMode=yes\n");
}

pub fn emit_script(out: &mut [u8], w: usize, r: TriRemoteReq) -> usize {
    if (r.golden == false) {
        return emit_str(out, w, SCRIPT_PLAIN);
    }
    let mut p: usize = emit_str(out, w, GOLDEN_FETCH);
    p = emit_str(out, p, r.url);
    p = emit_str(out, p, GOLDEN_INSERT);
    p = emit_dec(out, p, r.threads);
    return emit_str(out, p, GOLDEN_SPLICE);
}

pub fn emit_ssh(out: &mut [u8], w: usize, host: &'static str) -> usize {
    let mut p: usize = emit_str(out, w, "ssh\n-o\nBatchMode=yes\n");
    p = emit_str(out, p, host);
    return emit_byte(out, p, 10);
}

pub fn emit_stem(out: &mut [u8], w: usize, deck: &'static str) -> usize {
    let b: usize = base_start(deck);
    let mut e: usize = deck.len();
    let mut i: usize = (b + 1);
    while (i < deck.len()) {
        if (deck.as_bytes()[(i) as usize] == 46) {
            e = i;
        }
        i = (i + 1);
    }
    let mut p: usize = w;
    let mut k: usize = b;
    while ((k < e) && ((k - b) < STEM_MAX)) {
        if (deck.as_bytes()[(k) as usize] == 46) {
            p = emit_byte(out, p, 95);
        } else {
            p = emit_byte(out, p, deck.as_bytes()[(k) as usize]);
        }
        k = (k + 1);
    }
    return p;
}

pub fn emit_str(out: &mut [u8], w: usize, s: &'static str) -> usize {
    let mut p: usize = w;
    let mut i: usize = 0;
    while (i < s.len()) {
        p = emit_byte(out, p, s.as_bytes()[(i) as usize]);
        i = (i + 1);
    }
    return p;
}

pub fn fits(out: impl AsRef<[u8]>, w: usize) -> usize {
    let out: &[u8] = out.as_ref();
    if (w > out.len()) {
        return 0;
    }
    return w;
}

pub fn is_alnum(c: u8) -> bool {
    return ((((c >= 97) && (c <= 122)) || ((c >= 65) && (c <= 90))) || ((c >= 48) && (c <= 57)));
}

pub fn name_span_ok(text: &'static str, from: usize, to: usize) -> bool {
    if ((to <= from) || ((to - from) > NAME_MAX)) {
        return false;
    }
    if ((text.as_bytes()[(from) as usize] == 45) || (text.as_bytes()[(from) as usize] == 46)) {
        return false;
    }
    let mut i: usize = from;
    while (i < to) {
        let c: u8 = text.as_bytes()[(i) as usize];
        if ((((is_alnum(c) == false) && (c != 95)) && (c != 45)) && (c != 46)) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

pub fn refusal(r: TriRemoteReq) -> u8 {
    if ((r.op == OP_NONE) || (r.op > OP_FETCH)) {
        return R_NO_ACTION;
    }
    if (r.host.len() == 0) {
        return R_NO_HOST;
    }
    if (safe_host(r.host) == false) {
        return R_BAD_HOST;
    }
    if (r.golden && (r.op != OP_RUN)) {
        return R_UNEXPECTED;
    }
    if ((r.op == OP_PING) && (r.name.len() > 0)) {
        return R_UNEXPECTED;
    }
    if ((r.op != OP_FETCH) && ((r.file.len() > 0) || (r.dest.len() > 0))) {
        return R_UNEXPECTED;
    }
    if ((r.op != OP_PING) && (r.name.len() == 0)) {
        return R_NO_NAME;
    }
    if (r.op == OP_RUN) {
        if ((r.golden == false) && (safe_deck(r.name) == false)) {
            return R_BAD_NAME;
        }
        if (r.golden && (safe_name(r.name) == false)) {
            return R_BAD_NAME;
        }
        if (safe_image(r.image) == false) {
            return R_BAD_IMAGE;
        }
        if (r.golden && (r.url.len() == 0)) {
            return R_NO_URL;
        }
        if (r.golden && (safe_url(r.url) == false)) {
            return R_BAD_URL;
        }
        if (r.golden && ((r.threads < THREADS_MIN) || (r.threads > THREADS_MAX))) {
            return R_BAD_THREADS;
        }
        return R_OK;
    }
    if ((r.op != OP_PING) && (safe_id(r.name) == false)) {
        return R_BAD_NAME;
    }
    if (r.op == OP_FETCH) {
        if (r.file.len() == 0) {
            return R_NO_FILE;
        }
        if (safe_name(r.file) == false) {
            return R_BAD_FILE;
        }
        if ((r.dest.len() > 0) && (safe_path(r.dest) == false)) {
            return R_BAD_DEST;
        }
    }
    return R_OK;
}

pub fn safe_deck(p: &'static str) -> bool {
    return (safe_path(p) && name_span_ok(p, base_start(p), p.len()));
}

pub fn safe_host(h: &'static str) -> bool {
    if (((((h.len() == 0) || (h.len() > HOST_MAX)) || (h.as_bytes()[0] == 45)) || (h.as_bytes()[0] == 64)) || (h.as_bytes()[((h.len() - 1)) as usize] == 64)) {
        return false;
    }
    let mut ats: usize = 0;
    let mut i: usize = 0;
    while (i < h.len()) {
        let c: u8 = h.as_bytes()[(i) as usize];
        if (c == 64) {
            ats = (ats + 1);
        }
        if (((((is_alnum(c) == false) && (c != 95)) && (c != 45)) && (c != 46)) && (c != 64)) {
            return false;
        }
        i = (i + 1);
    }
    return (ats <= 1);
}

pub fn safe_id(s: &'static str) -> bool {
    if (safe_name(s) == false) {
        return false;
    }
    let mut i: usize = 0;
    while (i < s.len()) {
        if (s.as_bytes()[(i) as usize] == 46) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

pub fn safe_image(s: &'static str) -> bool {
    if (((s.len() == 0) || (s.len() > IMAGE_MAX)) || (is_alnum(s.as_bytes()[0]) == false)) {
        return false;
    }
    let mut i: usize = 0;
    while (i < s.len()) {
        let c: u8 = s.as_bytes()[(i) as usize];
        if ((((((is_alnum(c) == false) && (c != 95)) && (c != 45)) && (c != 46)) && (c != 58)) && (c != 47)) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

pub fn safe_name(s: &'static str) -> bool {
    return name_span_ok(s, 0, s.len());
}

pub fn safe_path(p: &'static str) -> bool {
    if (((p.len() == 0) || (p.len() > PATH_MAX)) || (p.as_bytes()[0] == 45)) {
        return false;
    }
    let mut i: usize = 0;
    while (i < p.len()) {
        let c: u8 = p.as_bytes()[(i) as usize];
        if (((((is_alnum(c) == false) && (c != 95)) && (c != 45)) && (c != 46)) && (c != 47)) {
            return false;
        }
        if (((c == 46) && ((i + 1) < p.len())) && (p.as_bytes()[((i + 1)) as usize] == 46)) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

pub fn safe_url(s: &'static str) -> bool {
    if (((s.len() <= 8) || (s.len() > URL_MAX)) || (span_is(s, 0, 8, "https://") == false)) {
        return false;
    }
    let mut i: usize = 8;
    while (i < s.len()) {
        let c: u8 = s.as_bytes()[(i) as usize];
        if (((((is_alnum(c) == false) && (c != 95)) && (c != 45)) && (c != 46)) && (c != 47)) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

pub const FAIL: u8 = 1;

pub const PASS: u8 = 0;

